    (11, 19, "ር ፡፤9፡ በዚ. ፡ ዓለም ፡ እግዚአብሔር • ልጅን ፡ ሰጥቶ ታልና ፣ ደስ ፡ አለው = ሁሉን ፡ የፈጠረ ፡ አግ ዚጸብሔርንም ፡ በአፉ ፡ አመሰገነው።"),
