    (11, 24, "ስለዚያች ፡ በሪያ ፡ ልጅ ፣ ግን ፣ አት ን ! ከልጆችህ ፡ ወገን ፡ ነውና ፡ ብዙ ፣ ወገን ፡ ዴርገቀለሁ ፡ አለው።"),
