    (21, 19, "ታላቂቱ ፡ ካለች ፡ i ሽቱን ፡ a የሚሰስቀ፡፣ አንደሌለ ፡ በሰማይ ፣ ጽላት ፡ አንዳ ታውቆአል።"),
