    (22, 12, "በጎቹም ፣ ሁሉ ፡ ምልክት ፡ ያለውን ፡ ሁሉ ፡ አመ ድማውን ፡ ዝንጕኾርጕኾፋሩን ፡ ይወልዱ ፡ ጀመር።"),
    (22, 13, "ዳግመኛም ፡ በጎቹ ፡ በእነዚያ ፡ አምጻጓል ፡ ይወ ዱ ፡ ጀመር።"),
    (22, 14, "ምልክት ፡ ያለው ፡ ሁሉ ፡ ለያ ቆብ ! ምልክት ፡ የሌለው ፡ ለላበ ፡ ሆነ።"),
    (22, 15, "ያዕቆብ ፡ ገንዘቡ ፡ አጅግ ፡ በዛ ! ላሙንና ፡ ጉን ፡ አህሀያውንና ፡ ግመሉን ፡ ገዛ = ወንድ! ጅንና ፡ ሌት ፡ ልጅን ፡ ወለደ።"),
    (22, 16, "በ ፡ ልጆቹም ፡ በያፀቋቆብ ፡ቀነኑበት = በጎቹንም አርሱ ፡ ሰበሰበ + በክፉ ፡ አስተያየትም ፡ ይመ ከተው ፡ ዩመር።"),
    (22, 17, "ራሔል ፡ዮሴፍን ፡ ከወለደች ፡ በኋላ ፡ አንዲህ ነ ፤ የሦስት ፡ ቀን ፡ ጎዳና ፡ ያህል ፡ ከአርሱ ፡ ቀው ፡ ነበሩና ፡ላበ፡ በጎቹን ይሸልት ፡ ዘንድ ይ።"),
    (
        22,
        18,
        "ዕቆብም ፡ ላበ ፡ በጎቹን ፡ ይዘልት ዘንድ ፡ አን ቕድ ፣ አይቶ ፡ ራሔልንና ፡ ልያን ፡ ጠርቶ ፡ ከአር ፡ ጋር ፡ ወደ ፣ ከነዓን ፡ ይመጡ ፡ ዘንድ ልባቸው ፡ የሚገዛ ፡ ነገር ፡ ነገራቸው = በሕ ም ፡ ያየውን ፡ ሁሉ ፤ ወደ ፡ አበቱ ፡ቤት ፡ ይመ ስ ፡ ዘንድ ፡ የነገረውንም ! ሁሉ ፡ ነግሮአቹቸዋ ና።",
    ),
    (22, 19, "ወደምትሄድበት ፡ቦታ ሁሉ ፡ አኛም ፡ ከአንተ ፡ ር አንኙዳለን ፡ አሉት።"),
    (22, 20, "ዕቆብም ፡ የአባቱን ፡ የይስሐቅን ፡ አምላክ ፡ አባቱን ፡ የአብርሃምን ፣ አምላክ ፡ አመሰገነው።"),
    (22, 21, "ነሥቶ ፡ ልጆቹንና ፡ ሚስቶቹን ፡ በበቅሎ ፡ ስቀመጠ = ገንዘቡን ፡ ሁሉ ፡ ያዘ = ወንዙን ፡ ኻግሮ ፡ ገለዓድ ፡ ወደሚባል ፡ ጸገር ፡ ደረሰ።"),
    (22, 22, "ዕቆብም ፣ ለላበ ፡ ወደ ፡ አገሩ ፡ መሄዱን ፡ ሰወ ው = አልነገረውም።"),
    (22, 23, "በአራተኛው ፡ ሱበዔ ሰበተኛው ፡ ዓመት ፡ በመጀመሪያው ፡ ወር፡ ሀያ ፡ አንደኛው ፡ ቀን ፡ ያዕቁብ ፡ ወደ ፡ ገለ ድ ፣፡ ተመለሰ።"),
    (22, 24, "ላበም ፡ በኋላው ፡ ተከተለው።"),
    (22, 25, "በሦስተኛው ፡ ወር • በበተ ፡ በአሥራ ፡ ሦስተ ው ፡ ቀን ፡ያዕቁብን ፡ በገለዓድ ፡ ተራራ ፡ አገ ው።"),
    (
        22,
        26,
        "በሕልም ፡ ሴለ.ት ፡ ተናግሮታልና ፡፣ላበ፡ ያዕቆብ ፡ ላይ ፡ ክፉ ፡ ነገርን ፡ ያዶርግ ፡ ዘንድ፡ ግዚአብሔር ፡ አላሰናበተውም = በም ፡ ለያዕቆብ ፡ ነገረው = በዚያም ፡ ወር አሥራ ፡ አምስተኛው ፡ ቀን ፣ ያዕቆብ ፡ ለላባ ፡ ሪዳ ፡ አረደ ! ከእርሱ ፡ ጋር ፡ ለመጡ • ሰዎ ም ፡፣ሁሉ ፡ አረፉ።",
    ),
    (22, 27, "ንዱ ፡ አንዱን ፡ በተንኰል ፡እንዳይፈልገው፡ ዚያች ፡ ሌሊት ፡ በገለዓድ ፡ ተራራ ፡ ያዕቆብ ፡ ላባ ፡ ማለለት : ላባም ! ለያዕቆብ ፡ ማለለት።"),
    (22, 28, "ri BX ባበቴም ፡ ቤት ፣ እሄዳለሁ ፡ አለው።"),
    (22, 29, "በም ፣ ያፅቆብን ~~ በደመወዝ ፡ ከአኔ ፣ ጋር፡ ጓሣ፤ ተቀመጥ ፤ ዳግመኛ ፡ መንጋዎቹን ፡ ጠብቀልኝ ፣ ደመወዝህን ፡ ውሰድ ፡ አለው።"),
    (22, 30, "አመድማ + ዝንጐጕኾርገር + ነጭ ፡ ሆኖ ፡ የተወለ ጓሣስ፣ 1ዩ፣ ክርስቲያን ሃይማ ትና ሥርዓት ሌ = ፳ጽ፣ ቋጽይ፡ ግምብ ፡ ኖረ።"),
    (23, 1, "ዘ.የም ፣ ያፀቋብ ፡ ለአናቱና ፡ ለስኣበቱ ፡ ሁሉን በድ ፡ በር።"),
    (23, 2, "ከጊዜው ፡ በየፔኪው ፡ የፈለን ን ፡ ሁሉ ፣ ይልክ ፡ ነበር።"),
    (
        23,
        3,
        "| ያዕቆብንም ፡ በፍጹም ፡ በውነታቸውና ፡ በፍ ፉም ፡ ልቡናቸው ፡ ይመርቁት ፡ ነበር ፣ በስድ ስተኛው ፡ ቡበዔ ፡ በመጀመሪያው ፣ ዓመት የሰቁማ ፡ ምሥራቅ ፡ ወደምትሆን ፡ ወደ፡ስሌም፡ በጸራተኛው ፡ ወር ፡ በተደላ ፡ በደስታ ፡ ወጣ።",
    ),
    (23, 4, "በዚያም ፡ የያፅቁብን ፡ ልጅ ፡ ዲናን ፡ ወደ ፡።"),
    (23, 5, "ገሩ ፡ ገቫ ፡ ወደ ፡ ኤዋቁዊን ፡ ስው ፡ ወደ ኤሞር ፡ ልጅ ፡ ወደ ፡ ሴኬም ፡ ቤት ፡ ነጥቀው ፡ ወሰዱአት።"),
    (
        23,
        6,
        "ደረሰበት ፡ አጐላቈላትም = እር ዋም ፡ የአሥራ ፡ ሁለት ፡ ዓመት ፡ትንሽ ፡ ልጅ በረች = ሚስት ፡ ሆና ፡ ትሰጠው ፡ ዘንድ ከአበትዋ ፡ ለመነ + ከወንድሞችዋም ፡ ለመነ።",
    ),
    (23, 7, "ዕቆብም ፡ ተቈጣ።"),
    (23, 8, "አሣግታቸውን ፡ ዲናን።"),
    (23, 9, "አጐስቀቍለዋታልና ፡ ልጆቹም ፡ በሰቁቂማ ዎች ፡ተቈጡ።"),
    (23, 10, "ከእነርሱም ፡ ጋር ፡ በተንከል፡ ናገሩ + አታለውም ፡ በዛበዙአቸው።"),
    (23, 11, "ፍዊና ፡ ስምያን ፡ ድንገት ፡ ወደ ፡ በቂማ ፡ ገብ ው ፡ በሰቂቁማ ፡ ስዎች ፡ ሁሉ ፡ መቻያን ፡ አደ ት።"),
    (23, 12, "በውስጥዋም ፡ ያገኙትን ፡ ሰው ፡ ሁሉ ፡ ገደሉ።"),
    (23, 13, "ንድ ፡ ሰው ፡ ስንኳን ፡ በውስጥዊ ፣ ጾላስቀሩም።"),
    (23, 14, "አግታቸው ፡ ዲናን ፡ አጐስቍለዋልና፡ቂስለው፡ ሉ ፡ሁሉን ፡ ገደሉ።"),
    (23, 15, "ንግዲህ ፡ ወዲህ ፡ ከዛሬ ፡ ጀምሮ ፡ የእስራኤ ን፡ልጅ ፡ ለማጐስቈል ፡ አንዲህ ፡ አታድርጉ።"),
    (
        23,
        16,
        "አስራኤል ፡ ኃፍረትን ፡ ስላደረ ፡ የሰቂቁማን፡ ዎች ፡ ሁሉ ፡ በሰይፍ ፡ ያጠፉአቸው ፡ ዘንድ ፡ ሰማይ ፡ ጽላት ፡ በአነርሱ ፡ ቅጣት ፡ ተጽፎአ ና ፡ አንዲህ ፡ አታድርጉ።",
    ),
    (23, 17, "በይፍ ፣ ያጠፉአቸው ፡ ዘንድ + በኣነርቡም።"),
    (
        23,
        18,
        "ይ ፣ ቅጣትን ፡ ያደርጉ ፡ ዘንድ + የአስራኤል ፡ ገን፡ የምትሆን ፡ ድንግልን ፡ ማገ°ስቈል ፡ በእ ራኤል ፡ዘንድ ፡ ከአንግዳኝህ ፡ ወዲህ ፡ አንዲህ፡ ክንዳይደረግ፡እግዚአብሔር፡በያዕቆብ፡ልጆች፡ ጅ ፡ ጣላቸው።",
    ),
    (
        23,
        19,
        "በጾስራኤል ፡ ዘንድ ፡፣ ልጅንም ፡ ቤሆን + አግቱ ም ፥ ቢሆን ፡ ከአሕዛብ ፡ ልጆች ፡ ለተወለደ ፡ ው ፡ ሁሉ ፣ ይሰጥ ፡ ዘንድ ፡ የወደደ ፡ ሰው ቢሪ ር = ሞትን ፡ ይሙት።",
    ),
    (23, 20, "ኃጢአትን ፡ ሠርቶ ልና ፥ በአስራኤልም ፣ ዘንድ ፡ ኃፍረትን ፡ ድርንአልና ፡ በድንጋይ ፡ ወግረው ፡ ይግደ ት።"),
    (23, 21, "ቲቱንም ፡ የአበትዋን ፡ ወገን ፡ ስም ፡ አስነቅ ለችና ፡ በአሳት ፡ ያቃጥሉት ፤ ከእስራኤል ፡ ተለይታ ፡ ትጥፋ።"),
    (23, 22, "አስራኤል ፡ ለኣግዚጸብሔር፡ ተልየ ፡ ገንዘብ ፡ ነውና ፡ በዚህ ፡ ዓለም ፡ በለ ፡ ችውልድ ፡ ዘመን ፡ ሁሉ ፡ በአስራኤል ፡ ዘንድ በኛ።"),
    (23, 23, "ጋጢጸተኛ ፡ጸይንኝ 5 . 964 Fy [4 wy tet Ll) [oy] Ly ime Si ክርስቲያን ሃይማኖትና ሥርዓት ሴ።"),
    (
        23,
        24,
        "፡ አነርጵም ፡ ዘአውነተኛ ፃት ፡ አንይ ፡ ተጠሩ ፡ የሴቁም ፡ ልጅ ፡ ለክህ፥ት ፡ አንደ ፡ ተመረጠ ኛ ፡ በዘመኑ ፣ ሁሉ ፡ አንዳገለገልን + ሴዋው ንም ፡ በአ“ግነኒኣብሔር ፡ ፊት ፡ ያገለግሉ ንድ ፡ አንደ ፡ ተመረጡ ፡ እይ።",
    ),
    (23, 25, "አውነት ፡ ነገ ን ፡ ይሠራ ፡ ዘንድ ፡ ፍርድንም ፡ ይፈርድ ፡።"),
    (23, 26, "ንድ ፡ በአስራኤል ፡ ላይ ፡ በጠላት፥ት ፡፣ ከሚ ሠ ፡ ብድራትን ፡ ይመልስ ፡ ዘንድ ፡ ቀንቶአ ና ፡ ሌሴ ፡ ይክበር ፡ ልጆቹም ፡ ለዘላለም ፡ ፎክ ሩ።"),
    (23, 27, "በሰማይ ፡ ጽላት ፡ ምስክር ፡ ሊሆን፣ ሁሉን ፡ወደ፥ ፈጠረ ፡ ወደ ፡ አግዚአብሔር ፣ ጽድቅና ፡ በረክ ን ፣ አንዲህ ፡ ያቀርቡልታል።"),
    (23, 28, "ፀው ፡ በሕይ ወት ‘ሳለ ፣ የሠራውን ፣ በጎ ፡ ሥራ ፡ እናስበለን።"),
    (23, 29, "በዓመት ፡ በዓመት ፡ በሚመላለሱ ፡ ጊዜዎች ፡ ሁሉ ፡ አስከ ፣ ቡህ ፡ ትውልድ ፣ ድረስ ፣ ያቀር ሉ።"),
    (23, 30, "በረከት ፡ ይመጣለታል + ከእርሱም ፡ ኋላ ፡ ለልጆቹ ፡ ይመጣላቸዋል።"),
    (23, 31, "በሰማይ ፡ ጽላት ፡ የአግዚአብሔር ፡ ወዳጅ ፡ ደሣ፡ ሰውም ፡ ተብሉ ፡ ተጻፈ።"),
    (
        23,
        32,
        "ይህን ፡ ሁሉ ፡ ነገር ፡ ጻፍሁልህ = „ኃጢእት ፡ አንዳይሠሩ ፡ ክከሥርዓ ትም ፡ አንዳ ይተላለፉ ፡ ይሠሩአት ፡ ዘንድ ፡ ይጽ ፉአትም ፡ ዘንድ ፡ የእግዚአብሔር ፡ ወዳጆችን ፡ ሁነው ፡ ይጻፉ።",
    ),
    (24, 1, "የተሠራላቸውንም ፡ መሐላ ፡ እንዳያፈርሱ ፡ ለአስራ ኤል ፡ ልጆች ፡ ትነግር ንድ ፡፣ አዘዝሁህ።"),
    (
        24,
        2,
        "መሐላውን ፡ ቢያፈርሱ = ከኃጢአት ፡ ሥራ ፡ ወገንም ፡ ሁሉ ፡ ቢሠሩ ፡ ግን ፡ ጠላቶች ፡ ሆነው ፡ በሰማይ ፡ ጽላት ፡ ይጻፋሉ ፣ ከሕያዋንም፣ መጽ ሐፍ ፡ ይጠፋሉ + የሚጠፉ ፡ ሰዎች ፡ በሚጻፉ በትም ፡ መጽሐፍ ፡ ይጻፉሉ።",
    ),
    (24, 3, "ከምድር ፡ ላይ ከሚጠፉ ፡ ሰዎችም ፡ ጋር ፡ ይቈጠራሉ።"),
    (
        24,
        4,
        "የያዕቆብም ፡ ልጆች ፡ ሰቁቂማን ፡ በጠፉበት ፡ቁን፡ ቀና ፡ ነገርንና ፡ አውነት ፡ ሥራን ፡ አንደ ፡ ሠሩ + በሰቁቂማ ፡ ሰዎችም ፡ ብድርን ፡ አንደ ፡ መለሱ ፡ በሰማይ ፡ ጽላት ፡ ተጻፈላቸው።",
    ),
    (24, 5, "በረ ከትንም ፡ ስለመቀበል ፡ ተጻፉ።"),
    (24, 6, "እኅታቸውን ፡ ዳናንም፡ ከሴሌኬም፡ቤት፡አወጡ።"),
    (24, 7, "በሰቁማ ፡ ያለውንም ፡ ሁሉ ፡ በጎቻቸውንም ለሞቻቸውንም ፡ አሀዮቻቸውንም ፡ ገንዘበቸው ንም ፡ ሁሉ ፡ መንጋቸውንም ፡፣ ሁሉ ፡ ማረ።"),
    (24, 8, "ሁሉንም ፡ ወደ ፡ ኣበታቸወ' ፡ ወደ ፡ ያዕቁብ ፡ አመጡ።"),
    (24, 9, "በዚያ ፡ ከሚኖሩ።"),
    (24, 10, "ከፈሪሳውያንና ፡ ከከነናው ን ፡ የተነሣ ፡ ፈርቶአልና ፡ አገሩን ፡ ስላጠፉ ከእርሱ ፡ ጋር ፡ ተነጋገረ።"),
    (24, 11, "በሰቁማ ፡ ዙሪያ ፡ በሉ ፡ አገሮች ፡ ሁሉ ፡የአግዚ አብሔር ፡ መፈራት ፡ ተደረገ።"),
    (24, 12, "በኣነርሱ ፣ ድን ጋጤ ፡ መጥቶአልና ፡ የያዕቆብን ፡ ልጆች ፡ ለማ ሰደድ ፡ አልተነሠውም።"),
