    (24, 14, "ከወንድሜ ፡ ከዔሳው ፡ ፊት ፡ በሸሸሆ ፡ ጊዜ 1B፣ ፳h፡ ጸፒ፡ ጾ8፡ ካርስቲያን ሃይማናኛትና ሥርዓት።"),
    (
        24,
        15,
        "፡ አንድነት ፣ ጸቅፎ ፡ ሰኻቸው ፣ ትንቢት ፣ የሚያ ፍግር ፡ መንፈስ ፣ ቀዱስ ፡ በጸ ፡ አናገረው ፣ ሌዊን ፡ በቀኝ ፡ አጁ ፡ ያዘው ፣ ይሁዳንም ፡በግራ፡ እኝ ያዘ።",
    ),
    (24, 16, "መጀመረያ ፡ ወደ ፡ ሌዊ ፣ ተመልስለ ፡ ከይሁዳ ፥ አስቀድሞ ፡ ይመርቀው ፡ ጀመር።"),
    (
        24,
        17,
        "እርሱ ፡ አግዚአብሔር ፡ ያክብርህ ፣ ዓለሙን ፡ ሁሉ ፥ የፈጠረ ፡ ፈጣሪ ፣ ልጆችህንና ፡ እንተን ፡ በ5 ለሙ ፡ ሁሉ ፡ ያክብር ፤ ክብር ፡ ለ.ሆንህ ፡ አግዚ አብሔር ፡ ለእንተ ፡ ገናንነትን ፡ ይስጥህ ፣ ለልጆ ቷችህም ፡ ይስጣቸው።",
    ),
    (
        24,
        18,
        "አንተን ፡ ወይ ፡ አርሱ ፡ ያየቅርብህ ፣ በቤተ ፡ መቅ ደስክ ፡ ያገለግሉት ፡፣ዘንድ ፡ ከሰው ፡ ሁሉ ፡ ለይቶ ልጆችህንም ፡ ወደ ፡ አርሱ ፡ ያየቅርበቸው ፤ ባለ ምዋልነት ፡ አንዳላቸው ፡ አንደ ፡ ከበሩ ፡ አንደዶ፡ ሊቃነ ፣፡ መላአክትም አንደ ፡ እነርሱ ፡ ልጆች ህም ፡ ለክብር ፡ ለጌትነት ፣ ለምስጋና ፣ ይሁኑ ፤ በንለሙ ፡ ሁሉ ፡ ከፍ ፡ ከፍ ፡ ያድርጋቸው ፤ ለያ ዕቆብ ፡ ልጃች ፡ ወገኖች ፡ ሁሉ ፡ መሳፍንትና።",
    ),
    (24, 19, "መኳንንት ፡ አለቆችም ፡ ይሆናሉ።"),
    (
        24,
        20,
        "የእማግዚጸብሔርንም ፣ ነገር ፡ በአውነት ፡ ይናገ | ራሉ ፣ ፍርዱንም ፡ ሁሉ ፣ በአውነት ፡ ይፈር ዳሉ ፤ ለያዕቆብ ፡ ዘጠኙን ፣ ሕግጋት ፡ ለአስራ ኤልም ፡ አምልኮቱን ፡ ይናገራሉ ፣ የያዕቆብን ልጅ ፡ ሁሉ ፡ ይመርቁ ፡ ዘንድ ፡ የእግዚአብ ሔር ፡ በረከት ፡ በአፋቸው ፣ ይነገራል።",
    ),
    (24, 21, "አንተንም ፡ አናትህ ፡ ስምህን ፡ ሌቁ ፡ ብላ ጠራች።"),
    (24, 22, "ስምህንም ፡ በአውነት ፡ ጠራች ! ከእ ግዚጸብሔር፡ጋር፡ አንድ ፡ ትሆናለህ፤፣ክያዕቆብ፡ ልጆች ፡ሁሉ ፡ ጋር ፡ አንድ ፡ ትሆናለህ ፣ ማዕዱ ለአንተ ፡ ትሁን።"),
    (
        24,
        23,
        "ልጆትህና ፡ አንተ ፡ ብሉአት ፤ ማዕድሀም ፡ ለልጅ ፡ ልጅ ፡ሁሉ ፡ የመላች፡ትሁን፣ በዓለሙ፡ ሁሉ ፡ አህልህ ፡ አይጐጕደል ፥ አይታጣ ፣ የሚጠ ሉህም ፡ ሰዎች ፡ ሁሉ ፡ በፊትህ ፡ ይውደዥ፥ ጠላቶችህም ፡ሁሉ ፡ ፈጽመው ፡ይጥፉ፤ሁሉም፡ የተረገሙ ፡ ይሁኑ ፡ አለው = ይሁዳንም, የሚጠሉህን ፡ በዎች፡ሁሉ፡ ታጠ ፋቸው ፡ ዘንድ ፡ አግዚአብሔር ፡ ኃይልን ፣ ጽና ትን ፡ ይስጥህ ፤ አንተ ፡ ገዥ ፡ሁን ፤ ከልጆች ሀም ፡ አንዱ ፡ ለያዕቆብ ፡ ልጆች ፡ ገዥ ፡ ይሁን፣ ስምህ • ከልጆ ችህ ፡ ስም ፡ ጋር ፡ በከተማውና ፡ በሀገሩ ፡ ሁሉ ፡ ሲጠራ ፡ የሚኖር ፣ ይሁን = ያንጊዜ ፡ አሕዛብ ፡ ከፊትህ ፡ የተነሣ ፡ ይፈራሉ ፥ አሕዛብም ፡ ሁሉ ፡ ይታወክሉ = ሕዝቡም።",
    ),
    (24, 24, "ሁሉ፡ ይሸ በራ ሉ ፣ የያፅቆብ፡ ረድኤት ፡ በአንተ ይደር + የአስራኤልም ፡ ድግነት ፡ በአንተ ፡ ትግ ኛለች።"),
    (
        24,
        25,
        "እውነተኛ ፡ ክብር ፡ በለው ፣ ዙፋን በተቀመ ጥህ፡ጊዜ፡ገናና ፡ ትሆናለህ ፤ ለያዕቆብ፡ልጆች፡ ሁሉ ፡ ብዙ ፣ ተድላ ፡ ዶስታ ፡ ትይረግላቸዊዋ ለች ፣ የሚመርቅህ ፡ ሰበው ፡ የተመረቀ ፡ ነው የሚጠሉህ ፡ መከራንም ፡ የሚያየጸኑብህ፡ የሚ ረግሙህም ፡ ሁሉ ፡ ክቫህ ፡ ዓለም ፡ ፈጽመው።",
    ),
    (24, 26, "966 tft je) Ly) ክርስቲያን ሃይማናችትና ቋ፪፡ ፳፻ g መሰገነው።"),
    (24, 27, "ሁንም ፡ ለዘላለም ፡ ተስፋ ፡ አንዳለኝ ሁሉን ፡ ፈጠረ ፡ በአግዚአብሔር ፡ ፊት ፣ ለልጆቹም ፡ በፋ ፣ አንዳላቸው ፡ አወቅሁ ፡ አለ።"),
