    (25, 1, "ዚያም ፡ ወራት ፡ ራሔል ፡ ልጅዋን ፡ ብንያ ን ፡ ፀነሰች ፤ ያዕቁብም ፡ ከሮቤል ፡ ጀምሮ።"),
