    (25, 6, "ሥራት ፡ ያወጣ ፡ ዘንድ ፡ ከተሳለው ፡ ስእለት መሥዋዕታቸው ፡ ጋር ፡ ያቀረበው ፡ መበ።"),
    (25, 7, "፡ ነው = ልቅ ፡ ኣድርገው ፡ የሚያፈሱ ም ፡ ከዚህ ፡ ጋር ፡ አንድ ፡ ነው።"),
    (25, 8, "ት ፡ በበላው ፡ +ዜ ፡ በአሳቱ ፡ ላሬ ፡፣ነጭ።"),
    (25, 9, "፡ ጣንን ፡ ያጥን ፡ ነበር = ዶግንነት ፡ ለሚደረግ ፡ መሥዋዕትም ፡ አራት ፡ ገች =+ አራት።"),
    (25, 10, "ግ ፣፡ሙክት ፥ አራት ፡በግ ፥ ለራት ፡ የፍየል ክት ፥ ዓመት ፡ የሆናቸውን ፡ ሁለት ፡የበግ፡ ቦቶች + ሁለት ፡ የፍየል ፡ ጠቦቶችን ፣ ያቀ ፡ ነበር።"),
    (25, 11, "በነጋ ፡ ቀጥር ፡ ሰበት ፡ ቀኘ ፣ አን ፡፣ ያደርግ ፡ ነበር።"),
    (25, 12, "ቤተ ፡ ሰቦቹና ፡ ከልጆቹ ፡ ሁሉ ፡ ጋር ፣ ዴስ ፡።"),
    (25, 13, "ሎት ፡ ሰበት ፡ ቀን ፡ በዚያ ፡ ይበላ ፡ ነበር።"),
    (25, 14, "ጽኑ ፡ መከራ ፡ ሁሉ ፡ ያዳነውን ፥ የለመነው ፡ የስጠውን ፡ አእግዚጸብሔርን ፡ ፈጽሞ።"),
    (25, 15, "መሰግነው ፡ነበር።"),
    (25, 16, "ንጹሕ ፡ የሆነውን ፡ ከብት ፡ ንጹሕ ፡ ያልሆነውንም ፡ አሥራት ፣አወጣ።"),
    (25, 17, "‘© ae ክርስቲያን ሃይማኛትና ፋሌ።"),
    (25, 18, "፳፫ ፡ ጋር፣ተነጋግሮ ፡ከጨረሰ፡በኋላ፡ ክአርሱ ፡ዘንድ፡ ወጣ።"),
    (25, 19, "ወደ ፣ ስማይ ፡ ኣስከኪ.ወጣ ፡ ድረስ ፣ ያዕቆ ብም ፡ ያይ፡ነበር።"),
    (25, 20, "ስሊት ፡ በራ.አይ ፡ በየ ፡ጊዜ ፥ አነሆ < መልአክ ከሰማይ ፡ ሲወርድ ፣ አየ ፣ ሰበት ፣ ብራናዎች ፡ በአጅ. ፡ አሉ።"),
    (25, 21, "ለያዕቆብ ፣ ሰጠው ፤ ያዕቆብም ፡ አነበበቸው 1 በዓለሙ ፡ ሁሉ ፡ ለልጆቹና ፡ለአርሱ ፡የሚሆን፣ በውስጣቸው ፡ የተጻፈውን ፡ ሁሉ ፡ አነበበ።"),
    (25, 22, "በብራና ፣ የተጻፈውን ፡ሁሉ፡ አሳየው።"),
    (25, 23, "ይህን ፡ ቦታ ፡ አትሥራ ፥ የዘላለም ፡ መቅደስ ንም ፡ አታድርገው ፤ ይህ ፡ ቦታ ፡ቤተ ፡ አግዚ አብሔር ፡ የሚሠራበት ፡ አይደለምና ፡ በዚህ ቦታ ፣፡ጾትዶር።"),
    (
        26,
        1,
        "ወደ ፡ አበትህ ፡ ወደ ፡ አብርሃም ቤት ፡ ሂድ ፣ አበትህ ፡ አስከሚሞትበት ፡ ቀን፡ ድረስ ፡ በዚያ ፡ በአበትክ ፡ በይስሐቅ • ቤት ኑር ፤፣ በግብጽ ፡ ሳለህ ፡ በደስታ ፡ ትሞታለህና በዚሀች ፡ አገር ፡ ከአበቶችህ ፡ ከአብርሃምና።",
    ),
    (
        26,
        2,
        "ከይስሐቅም ፣ ጋር ፡ በአበቶችህ ፡ መቃብር ፡ በክ ብር ፡ ትቀበራለህና ፡ ይዞህ ፥ ትፍራ ፣ አንዳ የኸው ፡ አንዳነበብ ኸው ፡ አንደዚሁ ፣ ይደረጋ ልና Ly አንተም ፡ ያየኸውን ፡ ያነበብኸውን ፡ ሁሉ ፣ ጻፍ ፡ አለው = ያዕቆብም - አቤቱ ፥ ሁሉን እንዳነበብሁ ፣ አንዳየሁ ፡ አንዴት ፣ አስበለሁ ? ይለ።",
    ),
    (26, 3, "ጌታም - ክኔ ፣ ሁሉን ፡ ጸኻስብሃለሁ አለው።"),
    (26, 4, "ከእርሱ ፣ ዘንድ ፣ ወጣ ፤ ያዕቆብም ፡ ከጸንቅልፉ፡ ተቀሰቀሰ ፣ያነበበውንና ፣ ያየውን ፡ ሁሉ ፡ አበበ።"),
    (26, 5, "ያየውንና ፡ ያነበበውን ፡ ነገር ፣ ሁሉ ፡ ጻፈ።"),
    (26, 6, "ዳማመኛ ፡ በዚያ ፡ አንድ ፡ ቀን ፡ በዓል ፡ አደረገ! በቀደሙት ፡ ዕለታት ፡ አንደሚሠዋው ፡ ሁሉ ፡ አድርጎ ፡ ሠዋበት።"),
    (26, 7, "ያች ፡ ቀን ፡ ተጨምራለችና፡ ስምቁዋን ፣ ተውሳክ ፣ ኣላት።"),
    (26, 8, "የቀደሙትንም ፣ ቀኖች ፡ በዓል ፡ ከእነርሱ በዓል ‘ትሆን ፣ዘንድ ፡ እርሱ ፡ አንዲህ ፡፣ ይታይ ነበር ፤ ይህም ፡ በሰማይ ፡ ጽላት ፡ ተጽፎአል።"),
    (26, 9, "ስለዚህም ፡ ነገር ፡ በዓል ፡ ያደርጋት ፡ ዘንድ = በዓል ፡ በሚደረግባቸው ፡ በሰበቱ፡ቀኖች፡ ላይ፡ እርስዋን ፡ ይጨምር ፡ዘንድ ፥ ስለዚህ ፡ ነገር፡ተገ ለጠለት።"),
    (26, 10, "በዓመት ፡ እንደሚመላለሱ ፡ ቀኖች ቍጥር ፡ በተድላ ፡ በደስታ ፡ መሥዋዕት ፡ የሚ ሠዋበት = በዓል ፡ የሚደረግበት ፡ ቀን ፡ ናትና ስምቁዊ ፡ ተውሳክ ፣ ተባለ።"),
    (26, 11, "ይህ ፡ ወር ፡ በበተ ፡ በሀያ ፡ ሦስት ፡ቀን ፡ በዚያ፡ ሴሊት፡የርብቃም፡ሞግዚትቁ፡ዲበራ፡ሞተችት።"),
    (26, 12, "ከመንደሩ፡ በታች ፡ በወንዝ፡ 5ር፡ በለ ፡ ግራር፡ ሥር ፡ ቀበሩት።"),
    (26, 13, "የዚያንም ፡ ወንዝ ፡ ስም ፡ ዲቦራ ፡ የተቀበረች በት ፣ ወንዝ ፡ ጸለው።"),
    (26, 14, "ግራሩንም ፡ የዲቦራ ልቅፅ ፡ የተለቀሰበት ፡ ግራር ፡ አለው።"),
    (26, 15, "ርብቃም ፡ ተመልሳ ፡ ወደ ፡ አበቱ ፡ ወደ ፡ ይስ ሐቅ ፣፡ ቤት ፡ ሄደች።"),
    (26, 16, "ያዕቆብም ፣ አበቱ ፡ አንደ ሚወደው ፡ አድርጋ ፡ ለጾበቱ ፡ ምግብ ፡ ታዛ ሥርዓት 968 1B! ፳B፣ [1 RE! ጽ8፣ ክርስቲያን ሃይማኖትና ሥርዓት።"),
    (26, 17, "አበቱ ፡ ሚስት ፡ የሚደርስ ፡ ሰው ፡ የአበቱን።"),
    (26, 18, "ፍረት ፣ ገልጦአልና ፡ የተረገመ ፡ ይሆን ፡ ንድ ፡ ዳግመኛ ፡ ተጽፎአል።"),
    (26, 19, "እግዚአብሔር ፡ ወዓናጀች ፡ ሁሉ የተረገመ፡ ሁን ፡ የተረገመ ፡ ሬሁን፡ አሉ።"),
    (26, 20, "ሴ ፥ ጸንተም ፡ የአስራኤልን ፡ ልጆች ፡ አዘ ቸው ፤ ስሞት ፡ የሚያበቃ ፡ ፍርድ ፡ ነውና + ማይገበ ፡ ነውና ፡ ፁን ፡ ነገር ፡ ይጠብቁ።"),
    (26, 21, "ን ፡ ክፉ ፡ ሥራ ፡ ለሠራ ፡ ሰው ፡ ለኃጠ.ጸቱ፡ ዘላለም ፡ ስርየት ፡ የለውም።"),
    (
        26,
        22,
        "ክከል ፣ ይህን ፣፡ ሥራ ፡ የሚሠረፈ.፡ሰው፡ ሁሉ ፡ ተናቀ ፡ የተጠላ ፡ ስለ ፡ ሆነ ፡ በዘህ ፡ ዓለም ንድ ፡ ቀን ፡ ስንኳ ፡ መዋል ፡ አይገባውምና ፡ አጸምላክችን ፡ ወገኖች ፡ መክከል ፡ በድንጋይ ወግሮ ፡ ይሙት ፡ አንጂ ፡ ለኃጢአቱ ፡ ስርየት ፡ ለውም = ኣበቱ ፡ ሚስት ፡ ዶዪርሰአልና ፡ ለሮቤል ፣ ድግሣ ፡ ስርየት ፡ ይገባዋል ፡ አይበሉ።",
    ),
    (
        26,
        23,
        "ርስወም ፡ በልቁ ፡ አበቱ ፡ የዕቆብ ፡ በሕይወት ፡ አስክዚያ ፡ ቀን ፡ ድረስ ፡ ሥርዓቱ ፡ ቅጣቱ፡፡ ፡ በጊዜው ፡ ጊዜ ፡ አንደሚደረገው፡ ሕግ፡ ልተፈጸመምና ፡ ስርየተ ፡ ይገበታል ፡ አይ = በልጅ ፡ ልጅ ፡ ዘመንም ፡ ለዘላለም ቶ ፡ የሚኖር ፡ ሕግ ፡ ይህ ፡ ነው።",
    ),
    (26, 24, "ህም ፡ ሕግ ፣ የዘመን ፡ ፍጻሜ ፡ የለውም።"),
    (
        26,
        25,
        "ሕዝቡ ፡ መክከል ፡ ሁለቱ ፡ ሁሉ ፣ አንድነት ፡ ጠፉ ፡ዘንድ ፥ ይህችን ፡ ኃጢእት ፡ በሠሩበት ፡ ይገድሎሉአቸው ፡ ዘንድ ፡ ነው ፡ እንጂ ፡ ጋጢዉአታቸው ፡ ምንም ፡ ስርየት ፡ የለውም = ሴ 2 አንተም ፡ ለእስራኤል ፡ ጻፍላቸው ጠብቁአት ም ፤አንደዚህ ፡ ያለ ፡ ሥራም ፡ አይ ፤ ለሞት ፡ የሚያበቃ ፡ በደልንም ፡ አይበ።",
    ),
    (26, 26, "ፊት ፡ አይቶ ፡ የማያዳላ + መማለጃን ፡ ይቀበል ፡ አርሱ ፡ አምላክችን ፡ ኣግዚአ ር ፡ አውነተኛ ፡ ዳኛ ፡ ነውና።"),
    (26, 27, "ሙ ፡ዘንድ + ይጠብቁ ፡ ዘንድ ፥ ከአነርሱም፡።"),
    (
        26,
        28,
        "ዩ ፡ ዘንድ + የተጠላ + የሚያስጸይፍ፥ የተ = የተነቀፈ ፡ ነውና ፡ ክዚህ ፡ ዓለም ፡ ፈጽ ፡ አንዳሮጠፉ ፡ በዚህ ፡ ዓለም ፡ በፈጣሪያ ፡ ፊት ፡ ይህችን ፡ ኃጢአት ፡ ለሚሠሩልት፡ ች ፡ ሁሉ ፡ ይሀንን ፣ የሥርዓቱን ፡ ነገር ፡ ራቸው።",
    ),
    (
        26,
        29,
        ") - ራኤል ፡ ለእግዚአብሔር ፡ የተለዩ ፡ ወገን ፡ ና = ለፈጣሪውም ፡ ማደሪያ ፡ ነውና + ለካህ ለመንግሥት ፡የሚገበ፡ወገን፡ነውና፡በዚህ፡ ም ፡ ከሚሠሩት ፡ ከዝሙት ፡፣ የሚበልጥ።",
    ),
    (26, 30, "በንጺሕ፡ ወገን ፡ መካከል ፡ ዲህ ፡ የለ ፡ ኃጢአት ፡ ለሠራ ፡ አይገበም።"),
