    (28, 16, "ይስሐቅም ~~ አኔም ፡ አውቃለሁ = አርሱ ፡ በፍ ጹም ፡ ልቡናው ፡ አንዲያከብረን፣ ከእኛ ፡ ጋር፡ ያለ ፡ የያፅቁቆብን ፡ ሥራ ፡ አያለሁ።"),
    (28, 17, "ቀድሞ ፡ ከተ ወለደበት ፡ ቀን ፡ ደምሮ ፡ ከያዕቁቆብ ፣ ይልቅ።"),
    (28, 18, "ቈሳውን ፡ አወደው ፡ ነበር ዛሬ ፡ ግን ፡ ከዔሳው ፡ ይልቅ ፡ ያዕቆብን ፣ እወዳ ለሁ።"),
    (
        28,
        19,
        "ክፉ ፡ ሥራውን ፡ አብዝቶአልና + ለእር ሱም ፡ በጎ ፡ ሥራ ፡የለውምና = ሥራው ፡ሁሉ፡ ሓኃጠ.አት ፡ በዴል ፡ነውና ፥ በልቡናውም፡ አው ነት ፡ ነገር ፣ የለውምና።",
    ),
    (
        28,
        20,
        "=: eet Lon Lig) Po] ክርስቲያን ሃይማኖትና ሥርዓት ፋ [iy is ጽደ 3 እኔ ፡ አንድወይዴው ፡ በሕይወት ፡ በኖርሁበት ከመን ፡ ሁሉ ፣ መቼም ፡ መቹ ፡ ከበጎ ፥ ነገር ፡ በቀር ፡ በአርሱ ፡ ክፉ ፡ ነገርም ፡ አንዳልፈልግ፡ እኔ ፡ አምልልሽለሁ ፡ አላት።",
    ),
    (
        28,
        21,
        "ከለዚ.ህ ፡ ሁሉ ፣ ነገር ፣ ማለላት ፤ የፅቋቆብንም በዔስው- ፡ ፊት ፣ ሕርታ ፡ ከሳው ፡ ጋር ፡ አንይ ተናገረችው ፡ ነገር ፡ አካክችትው = እኔ ፡ ፈቃድሽን ፡ አፈጽማለሁ ፣ በወንድሜ በዔሳው ፡ ከአኔም ፡ ከልጆቹም ፡ ክፉ ፡ ነገር ፡ኣን ዳይወጣ ፡ መቺም ፣ መቹ ፡ ከፍቅር ፡ በቀር ፡ አስ ቀድሚ ፣ አንዳልጣላ ፡ ተዋኽኝ ፡ አላት።",
    ),
    (28, 22, "እርስ ዋም ፡ ልጆችዋም ፡ በሉ፡ ጠጡ።"),
    (28, 23, "በዚያችም ፡ ሌሊት ፡ የሦስት ፡ ኢዮቤልዩ ፣ የአ ንድ ፡ ሱበዔ ፡ የአንድ ፡ ዓመት ፣ ልጅ ፡ የምት ሆን ፡ ርብቃ ፣፡ ሞተች።"),
    (
        28,
        24,
        "በዚያችም ፡ ሌለ.ት ፡ ሁለኝ፡ ፡ ልጆችዋ ፡ ሁሉ ፣ ያዕቆብና ፡ ዔው ፡ እጥፍነት ፡ በላት ፡ ዋጃ ፡ በአበታቸው ፡ አናት በሣሪ. ፣ መቃብር ፡ አጠገብ ፣ ቀበሩጸት።",
    ),
    (28, 25, "\\ በዚሀ ፡ ሱበዔ ፡ በስድስተኛው ፡ ዓመት ፡ ይስ ሐቀ ፣፡ሁለቱን ሁሉ ፡ ልጆቹን ፡ ያዕቆብና ፡ ዔሳ ውን ፡ ጠራቸው = ወደ ፡ አርቡያዎም ፣ መጡ።"),
    (28, 26, "ልጆቹ ፡ሆይ 1 አ።"),
    (
        28,
        27,
        "፡ አበቶቹ ፡ በሄዱበት ፡ ጐዳና አባቶቹ ፡ በዚያ ፡ ለዘላለም ፡ ወደምኖርበት ወደ ፡ መቃብር ፡ እሄዳለሁ ፣ አብርሃም ፡ ለመቃ ብር ፡ በገዛው ፡ ኣኔ ፡ ለራሴ ፥ በስቆፊርሀት በኬጡ፡ ሰው ፡ በኤፍሮን ፡ አርሽ ፣ በለች ፡ አጥ ነት ፡ በላት ፡ ዋሽ ፣ በአባቴ ፡ በአብርሃም ፡ አጠ ገብ ፡ ቅበሩኝ ፡ አላቸው = ልጆቹ ፡ ሆይ ! አግዚአብሔር ፣ ለአብርሃም ፡ያነ ረውን + ለልጆቹም ፡ የነገራቸውን ፡ ሁሉ ፡ አግዚአጸብሔር ፡ ለአናንተ ፣ ሁሉን ፣ አንዲያደር ግላችሁ ፡ በዚህ ፡ ዓለም ፡ የቀና ፣ ሥራና ፡ አው ሃት ፡ ሥራን ፡ ትሠሩ ፡፣ ዘንድ ፡ ይህን ፣ አዝዛች ጋለሁ = ልጆቹ ፡ ሆይ ! ስበው፡፣ ራቡን ፡ አንዲወድ ፡ እርስ በርሳችሁ ፡ ወንድሞቻችሁን ፡ አየ ወደዳችሁ ፡ ቸፍ = ሰው ፡ ለወንድሙ ፡ በጎ ፡ ነገርን ፡ በሚያደርግ ለች ፡ ገንዘብ ፡ ሲ.ፈልኝ + በዚህ ፡ ዓለም ፡ በል ቡናው ፡ ጾንድ ፡፣ ለመሆን ፡ ሲሽ + ጾርስ ፥ በርስ ቸው ፡ አንፎ ፡ ራሳቸው ፡ አንዲፋቀሩ ፥ ጸርስ በርስችሁ ፡ የምትፋቀፉ፡ ሁኑ።",
    ),
    (
        28,
        28,
        "ስሌ ጣያቱም ፡ ነገር ፡ እኔ ፡ አዝዛችኋለሁ ፤ ለሚ ያመልሹዙአቸው ፡ በሚሰግዱላቸውም ፡ ሰዎች፥ ጸነርፁ፡ ፡ ስሕተትን ፡ የተመሉ ፡ ናቸውና ፡ ትን ቁጸቸው ፡ ዘንድ ፡ ትጠሉሎጸቸውም ፣ ዘንድ እንዳትወዱአጸቸውም ፡ እኔ ፡ አዝዛችኋለሁ።",
    ),
    (28, 29, "ልጆቹ ፡ ሆይ ! የአባታችሁን ፡ የአብርሃምን ፥ አምላክ ፡ አግዚአብሔርን ፡ ጸስቡት።"),
    (28, 30, "ከዚህም ፡ በኋላ ፡ እኔ ፡ አመስክሁት።"),
    (29, 1, "በአውነት ፡ በኣውቀት ፡ በሰፋ ፡ ልቡናም ፣ ተገዛሁለት።"),
    (
        29,
        2,
        "ያበዛችሁ ፡ ዘንድ = ልጆቻችሁንም ፡ አንደ ሰማይ ፡ ኮከብ ፡ ለማብዛት ፡ ያሳድግላችሁ ዘንድ = ለዘላለም ፡ ስሚናር ፡ ትውልድ ፡ ሁሉ fs Ah AB a8 51 Ly) 5) ካርስቲያን ሃይማ ትና ሥርዓት።",
    ),
    (
        29,
        3,
        "ጽደ ፡ እሄ ይስሐቅም ፡ አሳርፋ ችሁኛልና = ስለ ፡ ማርጀ ቴም ፡ ልቡናዬ ፣ አላዘነችምና ፡ ልጆቹ ፡ ሆይ ፡ በዚሀች ፡ቀን ፡ በልጆቻችሁና በእናንተ ፡ላይ፡ በረክት ፣ ትዶር።",
    ),
    (29, 4, "ስለ ፡ አርስቁ ፡ ክፉ ሥራን እንዳትሠሩ በጎ ፡ ሥራ ፡ የሚሠራ ፡ ሰውን ፡ ልዕል ፡ አግዚአብሔር ፡ ያክብረው ፤ ልጁም።"),
    (29, 5, "እስከ ፡ ዘላለም ፡ ድረስ ፡ ጸንቶ ፡ ይኑር።"),
    (29, 6, "ይህን ፡ አዝዘዶቸውና ፡ መርቆአቸው ፡ ከeጨ ረሰ ፡ በኋላ ፡ በፊቱ ፡ አንድነት ፡ በሉ፡ ጠጡ።"),
    (29, 7, "በመካከላቸው ፡ መተካከል ፣ ሆኖጸልና ፡ ዶስ ፡ አላቸው።"),
    (29, 8, "ከአርሱ፡ ዘንድ ፡ ወጡ ፥ በዚያችም ቁን ፡ ሀርፈው፡ ተ።"),
    (29, 9, "ይስሐቅም ፡ ደስ ፡ ብሎት ፡ በዚያች ፡ ቁን ፡ በጸ ልጋው ፡ ላይ ፡ ተኛ ፤ የዘላለም ፡ አንቀልፍንም ጸንቀላፋ ሞት።"),
    (29, 10, "የመቶ ፡ ሰማንያ ፡ ዘመን ፡ ህያ ፡ አምስት ፡ ቡበጫና ፡ ጨረሰ።"),
    (29, 11, "ሁለቱ ፣ ሁሉ ፣ ሰው ፡ ቀበሩት።"),
    (29, 12, "ዔሳውም ፡ በኤዶምያስ ፡ አውራጃ ፡ ወዳለች ፡ ወደ ፡ ሴይር ፡ ሄደ + በዚያም ፡ ኖሪ።"),
    (29, 13, "ያዕቆብም ፡ አባቱ ፡ አብርሃም ፡ ተሰዶ ፡ ይኖር በት ፡ በነበረ ፡ በኬብሮን ፡ አውራኝ ፣ በለ ግምብ ፡ ኖረ።"),
    (29, 14, "እንደ ፡ ተወለደበት ፡ ወራት ፡ አንደሚታየው ፡ ትእዛዝ ፡ አድርን ፡ በፍጹም ፡ ልቡናው ፡ አግዚ ጸብሔርን ፡ አመሰገነው።"),
    (29, 15, "፣ በአርባ ፣ አምስተኛው ፡ ኢዮቤልዩ ፡ በሁለተ ኛው ፡ ሱበሩ ፡ በአራተኛው ፡ ዓመት ፣ ሚስቱ ፡ ልያ፡ ሞተች።"),
    (29, 16, "በአበቱ ፡ አናት ፡ በሣራ ፡ መቃ ር ፡ ግራ ፡ በአናቱ ፡ በርብቃ ፡ መቃብር ፡ አጠ ብ ፡ ሁለት ፡ ወገን ፡ በሆነች ፡ ዋኻ ፡ ቀበራት።"),
    (29, 17, "ልጆቹና ፡ ልጆችዋ ፡ ሁሉ ፡ ለሚስቱ ፡ ለልያ ፡ ከእርሱ ፡ .ጋር ፡ የለቅሱላት ፡ዘንድ ፡ ያለቅቁስላት፡ ነበርና ፣ ስለ ፡ እርስዋም ፣ ያረጋጉት ፣ ዘንድ መጡ።"),
    (
        29,
        18,
        "በሥራ.ቁ ፡ ሁሉ ፡ ፈጽማ ፡ ቀን ፡ ስለ ፡ ሆነች ፡ እሣትቁ ፡ ራሔል ፡ ከሞተች ፡ ጀምሮ ፡ ፈጽሞ ፡ ይወዳት ፡ ነበርና ፡ ያረጋጉት ፣ ዘንድ api = ያየዕቁብንም ፡ ታከብረው ፡ ነበርና = ከእርሱ ጋር ፡ በናየረችበት ፡ ዘመን ፡ ሁሉ ፡ ክፉ ፡ ነገር ፡ ከኣፍቁ ፡ አልሰማምና ፥ የዋህ ፡ ነበረችና ፥ ፍቅር ፡ ያላት ፡ ቅንነች ፡ ያላት ፣ ከብር ፡ ያላት ነበረችና።",
    ),
    (29, 19, "- በሕይወት ፡ ሳለች ፡ የሠራችውን ፡ ሥራ ፡ሁሉ፡ ያስብ ፡ ነበር።"),
    (29, 20, "በፍጹም ፡ ሰውነቱና ፡ በፍጹም ልቡናው ፡ ፈጽሞ ፡ ይወዳት ፡ ነበርና ፡ ያለቁስ ላች ፡ ነበር።"),
