    (30, 8, "ያዕቆብ ፡ ግን ፡ ወደ ፣፡ ግምቡ ፣ አጠንብ ኣስኪቀርቡ ፡ ድረስ ፡የነገሩትን ፡ አላመነም።"),
    (
        30,
        9,
        "የግምቡን፡፥ በር፡ ዘጋ በግምቡም ፡ ላይ ፡ ቁመ ከወንድሙም ፡ ከዒ ሳው ፡ ጋር ፡ ተነጋገረ - ሚስቴ ፡ ስለ ፡ ሞተች በበን ፡ማረጋጋት፡ታረጋጋኝ ዘንድ ፡ መጣህን ? እናትህና ፡ አበትህ ፣ ሳይሞቱ ፡ ዳግመኛ ፡ ፈጥ ነሀ ፡ የማልኸው ፡ መሐላ ፡ ይህ ፣ ነውን ? ከማልኸው ፡ መሐላ ፡ ወጥተህ ፡ በደልህ ለአበ ትህ፡በማልህበት ፡ ጊዜ ፡ ተፈረደብህ ፡ አለው።",
    ),
    (30, 10, "ዔሳውም ፡ ያን ፡ ጊዜ ፡ መለሰ።"),
    (30, 11, "ስለምድር ፡ አራዊትና ፡ ለሰው ፡ ልጆች ፡ እንዳይ ጣሉ ፡ በአውነት ፡ የተማማሉት ፡ መሐላ ፡ አስከ ዘላለም ፡ ድረስ ፡ የለቸውም።"),
