    (30, 22, "ያዕቆብ ፡ ግን ፡ በአዱራም ፡ በለች ፡ ኮረብታ ፡ ወንድሙን ፡ ቀብር ፡ ወደ ፡ ቤቱ ፡ ተመለሰ።"),
