    (31, 28, "ከዚህ ፡ በኋላ፡ የጠዬ ፡ አሳላፊዎች ፡ አለቃ ፡ዮሴ ፍን ፡ አሰበው + የአርሱንም ፣ ነገር ፡ በንጉሥ።"),
