    (37, 18, "ከጽኑ ፣ አገዛዝ ፥ ፉ ፡ ከምትሆን ፡ ከግብጽም ፣ ለመውጣት ፡ የተ ጋጀ ፡ ይሆን ፣ ነበር።"),
