    (37, 21, "የዘላለም! ሥርዓት ፡ነውና፡ ተወበሃነ ፣ ዘመን ፣ የለውም።"),
    (37, 22, "ው ፡ ንጹሕ ፡ ሆና ፣ ሰለ ፣ በጊዜው ፣ ጊዜ ፣ ዕለ ን ' ያዶርገው • ዘንድ ፡ በዓሉ ፡ በሚክበርባት፡ ን ፡ አግዘ. አብሔር ፡ ወዶ ፡ የሚቀበለውን።"),
